#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
    float stroke_length;     // 2..24 px along direction
    float stroke_density;    // 0.5..3.0 (more strokes)
    float grain_amount;      // 0..1
    float saturation_comp;   // 0..1 (compress saturation)
    float edge_tightness;    // 0..2 (sharper edges)
};

struct VIn { float4 pos [[attribute(0)]]; float2 uv [[attribute(1)]]; };
struct VOut { float4 pos [[position]]; float2 uv; };

vertex VOut main0(VIn in [[stage_in]], constant Uniforms &u [[buffer(0)]]) {
    VOut o; o.pos = u.MVP * in.pos; o.uv = in.uv; return o;
}

static inline float luma(float3 c){ return dot(c, float3(0.2126,0.7152,0.0722)); }

fragment float4 fragment_main(VOut in [[stage_in]], texture2d<float> src [[texture(0)]], constant Uniforms &u [[buffer(0)]]) {
    constexpr sampler s(address::clamp_to_edge, filter::linear);
    float2 texel = 1.0 / u.OutputSize.xy;
    float2 pix = in.uv * u.OutputSize.xy;

    float3 c0 = src.sample(s, in.uv).rgb;

    // Gradient-based direction (Sobel)
    float3 s00 = src.sample(s, in.uv + float2(-1,-1)*texel).rgb;
    float3 s10 = src.sample(s, in.uv + float2( 0,-1)*texel).rgb;
    float3 s20 = src.sample(s, in.uv + float2( 1,-1)*texel).rgb;
    float3 s01 = src.sample(s, in.uv + float2(-1, 0)*texel).rgb;
    float3 s21 = src.sample(s, in.uv + float2( 1, 0)*texel).rgb;
    float3 s02 = src.sample(s, in.uv + float2(-1, 1)*texel).rgb;
    float3 s12 = src.sample(s, in.uv + float2( 0, 1)*texel).rgb;
    float3 s22 = src.sample(s, in.uv + float2( 1, 1)*texel).rgb;

    float3 gX = (s20 + 2.0*s21 + s22) - (s00 + 2.0*s01 + s02);
    float3 gY = (s02 + 2.0*s12 + s22) - (s00 + 2.0*s10 + s20);
    float2 grad = float2(luma(gX), luma(gY));
    float mag = max(1e-4, length(grad));

    // Stroke direction aligned to gradient (pencil often follows edges)
    float2 dir = normalize(grad);
    // Per-pixel jitter to avoid banding
    float jitter = fract(sin(dot(pix, float2(12.9898,78.233))) * 43758.5453 + float(u.FrameCount)*0.013) - 0.5;

    // Accumulate samples along +/- dir to simulate strokes
    int taps = int(clamp(round(u.stroke_length/2.0), 2.0, 12.0));
    float3 accum = float3(0.0);
    float wsum = 0.0;
    for (int k=-taps; k<=taps; ++k) {
        float t = float(k);
        float2 off = (t + jitter) * dir * texel * (u.stroke_density);
        float w = exp(-abs(t) * (0.45 + 0.25*u.edge_tightness));
        float3 cs = src.sample(s, in.uv + off).rgb;
        accum += cs * w;
        wsum += w;
    }
    float3 stroke = (wsum>0.0) ? (accum/wsum) : c0;

    // Edge sharpening (tightness)
    float edge = smoothstep(0.2, 0.9, mag);
    stroke = mix(stroke, c0, 1.0 - clamp(u.edge_tightness*0.5*edge, 0.0, 1.0));

    // Saturation compression: pencil tends to compress saturation
    float L0 = luma(stroke);
    float3 satComp = mix(float3(L0), stroke, 1.0 - clamp(u.saturation_comp, 0.0, 1.0));

    // Fine grain (paper + graphite)
    float n1 = fract(sin(dot(pix, float2(127.1,311.7))) * 43758.5453);
    float n2 = fract(sin(dot(pix + float2(5.2,1.3), float2(269.5,183.3))) * 95732.5453);
    float grain = (n1*0.6 + n2*0.4) - 0.5;
    float3 pencil = saturate(satComp + grain * (u.grain_amount * 0.08));

    return float4(pencil, 1.0);
}

